diff.code:
let failures = 0;
let open = false;

async function callPayment(req) {
  if (open) throw new Error('circuit open');
  try {
    const res = await paymentApi.charge(req);   // no timeout
    failures = 0;
    return res;
  } catch (err) {
    failures++;
    if (failures >= 5) open = true;              // trips, but never resets
    throw err;
  }
}
